'use client';

import { useState, useEffect } from 'react';
import Link from 'next/link';

interface Product {
  _id: string;
  name: string;
  asin: string;
  url: string;
  priceHistory: { price: number; date: string }[];
  thresholdPrice: number;
  trackedBy: number[];
}

export default function DashboardPage() {
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchProducts() {
      try {
        const res = await fetch('/api/dashboard/products');
        if (!res.ok) {
          throw new Error(`Error: ${res.status}`);
        }
        const data = await res.json();
        setProducts(data);
      } catch (err: any) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    }
    fetchProducts();
  }, []);

  if (loading) return <div className="flex min-h-screen flex-col items-center justify-center p-24">Loading products...</div>;
  if (error) return <div className="flex min-h-screen flex-col items-center justify-center p-24 text-red-500">Error: {error}</div>;

  return (
    <main className="flex min-h-screen flex-col items-center justify-between p-24">
      <h1 className="text-4xl font-bold mb-8">Product Dashboard</h1>
      <Link href="/dashboard/admin" className="text-blue-500 hover:underline mb-4 block">Go to Admin Dashboard</Link>
      <div className="w-full">
        <table className="w-full table-auto border-collapse border border-gray-400">
          <thead>
            <tr className="bg-gray-200">
              <th className="border border-gray-300 px-4 py-2">Name</th>
              <th className="border border-gray-300 px-4 py-2">ASIN</th>
              <th className="border border-gray-300 px-4 py-2">URL</th>
              <th className="border border-gray-300 px-4 py-2">Current Price</th>
              <th className="border border-gray-300 px-4 py-2">Threshold Price</th>
              <th className="border border-gray-300 px-4 py-2">Tracked By</th>
              <th className="border border-gray-300 px-4 py-2">Details</th>
            </tr>
          </thead>
          <tbody>
            {products.map((product) => (
              <tr key={product._id}>
                <td className="border border-gray-300 px-4 py-2">{product.name}</td>
                <td className="border border-gray-300 px-4 py-2">{product.asin}</td>
                <td className="border border-gray-300 px-4 py-2"><a href={product.url} target="_blank" rel="noopener noreferrer">Link</a></td>
                <td className="border border-gray-300 px-4 py-2">{product.priceHistory.slice(-1)[0]?.price || 'Price data not available'}</td>
                <td className="border border-gray-300 px-4 py-2">{product.thresholdPrice}</td>
                <td className="border border-gray-300 px-4 py-2">{product.trackedBy.length}</td>
                <td className="border border-gray-300 px-4 py-2">
                  <Link href={`/dashboard/product/${product.asin}`} className="text-blue-500 hover:underline">
                    View
                  </Link>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </main>
  );
}
